    "描述": "村长老杰克登门通知：三天后诺丁城武魂殿执事将来村主持一年一度的觉醒仪式，快满六岁的唐三应当参加，并向唐三讲解了魂士至封号斗罗的十级称号体系与魂师在大陆的崇高地位。当晚唐三完成一万锤，捧出乌黑发亮、仅余四分之一大的铁块，唐昊验看后食言不教锻造，改命他继续把铁块锻到拳头大小。唐三由此与这块生铁较上了劲，每日敲打速度递增，将这份倔强视作对自身意志的磨砺。老杰克临走前拍着唐三肩膀笑言，觉醒日若出好武魂他请全村喝酒。",
