    "描述": "次日离开住了两日的玫瑰酒店，两人出索托城南门一路南下，唐三感念唐昊离村六载音讯全无，心中隐痛难消，小舞则一路缠着唐三背她赶路、指指点点说不出的开心。行至一处约百户人家的小村，村口木质拱门悬挂着一块破旧牌匾，赫然写着「史莱克学院」五字，一枚绿色人形怪物头像徽记令二人愕然对视——报名的少年与家长已排起长长队列。唐三感念唐昊离村六载音讯全无心中隐痛难消，小舞则一路缠着背她赶路指指点点说不出的开心，两人在夕阳余晖中走到村口。",
    "简述": "南行途中意外抵达简陋村落，惊见「史莱克学院」破旧牌匾。"
