    "描述": "眼见小舞受伤，戴沐白一声令下与朱竹清释放两人埋藏已久的武魂融合技“幽冥白虎”——双体消融合一，化作通体透明、黑纹白毛的巨虎，一爪拍碎黑豹魂师奥斯罗的分身，再迎着玉天恒拼死一击的雷霆万钧碾压而过，将队长与黑豹魂师同时震飞重创，皇斗战队最具威胁的两名战力就此彻底失去战斗力。",
    "简述": "戴沐白朱竹清释放幽冥白虎，重创玉天恒与奥斯罗。"
