    "描述": "唐三继续向牛皋剖陈心迹:唐门之立,除私心之外,更为遏制武魂殿裹挟数万低阶魂师形成的恐怖军团——若唐门能为两大帝国官方大批供应暗器,战时便可扭转以寡敌众的绝对劣势;又坦承昊天宗二十年封闭并非虚耗,门下六位封号斗罗蓄势待发,未来天下大乱之际,唐门的分量绝不逊于昊天宗本身,并郑重承诺唐门永不被昊天宗收编、御之一族去留自主。牛皋反复权衡家族存续与武魂殿步步紧逼的现实,终于一拍即合,与泰坦紧紧相拥——御之一族正式决定携全族两百余人迁往天斗城,加入唐门。这一夜,唐门首度收获除力之一族外的第二大根基。",
    "简述": "唐三剖陈唐门抗魂殿之志打动牛皋,御之一族决意举族加入唐门。"
