    "描述": "离开皇宫时宁风致追上唐三,低声告诫:瀚海乾坤罩在帝国典籍中有一条记载——曾有三位先帝试图以精神力沟通此物,无一例外精神受创、其中一位甚至因此折寿十年。宁风致叮嘱唐三务必循序渐进切勿急躁,又交代自己将在唐三离开期间全力维护唐门在帝国的利益与地位。唐三握住国师的手郑重道谢,心中对这位沉稳可靠的盟友又多了几分信赖与敬意，此刻的氛围令人既紧张又充满期待，空气中弥漫着一种难以言喻的肃穆气息。",
    "简述": "宁风致警告三位先帝探查此物均受创,叮嘱循序渐进并承诺维护唐门。"
