    "描述": "全歼三百余狼盗后三人浑身浴血瘫坐于尸堆之间,马红俊凤凰双翼已碎裂大半、戴沐白胸前三道深可见骨的爪痕仍在渗血、唐三八蛛矛因过度吞噬异种能量而发烫龟裂。三人默默对视,唐三取出恢复香肠分给二人,又从狼盗首领尸体中取出那块淡青色魂骨。马红俊抹去嘴角鲜血苦笑:这一战打得比大赛决赛还惨,唐三点头:但也正因如此,我们三个的配合已经找回了当年的感觉——生死之间锤炼出的默契,是任何训练都无法替代的。",
