    "描述": "战后天色微明,三人强撑疲惫为死难村民挖掘了一个简易的集体墓穴,将百余具残躯尽数安葬。戴沐白以白虎之爪在石碑上刻下无辜者安息几个大字,马红俊则以凤凰余焰将狼盗尸体焚烧殆尽不留一丝痕迹。唐三含泪向墓碑三鞠躬,默默立誓:日后唐门暗器量产之时,优先供给边境村镇民兵使用,绝不让这样的惨剧重演。三人在晨光中沉默离去,身后只余袅袅青烟与一座无名者的安息之地，整个场景犹如一幅凝固的画卷般深刻。",
    "简述": "三人为死难村民安葬立碑,唐三默誓日后优先供暗器予边境百姓防身。"
