    "描述": "唐三背起宁荣荣强攻阶梯，以蓝银皇与两大领域全力护她，行至一百二十级台阶时她口吐鲜血几近崩溃，唐三当机立断释放蓝银真身将二人一同包裹，虽自身承压骤增仍径直冲上一百三十六级台阶。宁荣荣当场触发红光冲破领域，完成顶级七考——不仅魂力晋升七十级，六个魂环更各自增益五百年修为，第二魂环由黄转紫，成为七怪中除唐三外首个尝到顶级考核厚赐的人，唐三也因倾力相助而元气大伤，需要长时间调息恢复。",
    "简述": "唐三背负宁荣荣硬闯一百三十六级台阶，助其完成顶级七考。"
