    "描述": "海马圣柱所在的海中海，黎明时分七怪抵达开考。波赛西重申规则：三十六个时辰内七人须全部过关，失败者一年之内可以重考，圣柱守护者不得动用圣柱本身的海神之力，否则算作违规。她随后引动七道光柱汇成一簇计时的光团，光团每暗一分便代表一名守护者落败，众人抬头便能看清进度。小舞在瀚海护身罩的掩护下隐身随行，连波赛西也未点破她也来到了阵前。唐三抬手示意，第一个走向海马圣柱，三十六个时辰的倒计时自此启动。",
