    "描述": "海神山脚下，唐三抬头沉声道出第七考的内容：神器，拔出，海神的三叉戟。宁荣荣的考题是辅助唐三完成第七考，小舞的仍是跟随。短短十个字令所有人静了下来——马红俊直言问出众人心中的疑惑：这海神九考莫非真是要成海神，这神器便是神所用的武器？唐三亦按下心中的震动，只说不论意义如何都要先通过才能明白，切莫抱太高奢望。戴沐白稳住众人：不论意义如何，先让小三真正试过这一考再说。唐三亦按下心头的震动，只叮嘱众人先把力气用在修炼上。",
    "简述": "第七考公布为拔出海神三叉戟，众人震动，马红俊直问是否要成神。"
