    "描述": "海神殿内，波赛西道出成神的真章：这世界有自己的规则，九十九级即是规则上限，突破规则便是神；凭个人之力不可企及，海神当年靠的是千万万海魂兽与海魂师的信仰之力。她与千道流既已成为信仰者便无接受信仰之力的资格。另一条捷径是得先辈之神认可、继承已有神诋——神成神后只能在此世存在百年，离去时留下部分神念与神诋。唐三，正是被海神选中的那个人。宁荣荣与小舞听得呆住，小舞更是惊骇地捂住了自己的嘴。",
