    "描述": "斗罗大陆西北海岸，行船三日后地平线终于出现，众人欢呼出声。小白以海图确认位置后告别，并约定回程时只需在此释放三叉戟的光芒，她三日内必来相迎，随后在海中回首三次带族人加速远去。唐三就地摊开地图定下分途：他携小舞向正东约十日抵星斗大森林猎取魂环，其余人向东北取官道约二十日返天斗城，先行探明大陆四年之变。小白在海中回首三次，才带着族人加速消失在水天相接处。众人望着渐远的鲨影，心头都有几分怅然若失。",
