    "描述": "唐三以控鹤擒龙操昊天飞锤虎入羊群般扫杀四五十级魂师群，杀神领域纹路每杀一人闪过血光令锤身煞气递增、自动破防；唯一的七十级血魔斧魂圣虽挡住一击却虎口震裂，命令余众分散逃跑自己断后。唐三瞬间转移截断逃路，蓝银皇与八蛛矛封锁各方向出口，随后首次在实战中正式挥动海神三叉戟——十万八千斤巨力加杀神领域双重增幅之下一戟横扫，魂圣连同其身后数人俱碎，三叉戟主刃过处空间都扭曲震颤。全歼八十名魂师无一逃脱，士兵与奴仆尽数昏迷未伤一人。",
