    "描述": "唐三将飞行蘑菇肠的战术运用详细规划——万名唐家军分三波升空：第一波四千人从正面城墙上方齐射压制守城魂师、第二波三千人从侧翼斜射覆盖城内集结点、第三波三千人作为预备队补射或应对突发状况。每人携带三管诸葛神弩——齐射一轮后换管再射，三轮齐射共近五十万支弩箭可在两分钟内完成。奥斯卡自信表示十天内制造两万根飞行蘑菇肠不成问题——他已突破八十级后食物系魂技产量翻倍且品质更稳定，每根可维持飞行两刻钟足够完成三轮齐射。",
