    "描述": "千仞雪以天使之神降临嘉陵关后在帅帐中独处——她已做好死的准备但并不恐惧。天使神装映照出她精致冷漠的面容——二十五岁的外表下藏着一颗早已历经沧桑的心。千仞雪最后一次以天使神念扫描整片大陆试图感知唐三的位置——但海神领域的隐匿效果令她完全无法锁定。她收回神念微微笑了——'来吧唐三，不管你有没有成神我都已经准备好了。这是我最后一次为你心跳的机会了。'千仞雪以手贴胸感受逐渐平静的心跳——明天之后这颗心将为谁而跳已不重要。",
    "简述": "千仞雪在帅帐独处以天使神念搜索唐三未果后微笑接受命运，感受最后为他心跳的夜晚。"
